root.command:

IF OBJECT_ID(N'dbo.WooCategoryFilterTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.WooCategoryFilterTbl', N'ExcludeFromSync') IS NOT NULL
BEGIN
    DECLARE @sqlExclude nvarchar(4000);
    SELECT @sqlExclude = N'ALTER TABLE dbo.WooCategoryFilterTbl DROP CONSTRAINT ' + QUOTENAME(dc.name)
    FROM sys.default_constraints dc
    INNER JOIN sys.columns c ON c.default_object_id = dc.object_id
    WHERE dc.parent_object_id = OBJECT_ID(N'dbo.WooCategoryFilterTbl')
      AND c.name = N'ExcludeFromSync';
    IF @sqlExclude IS NOT NULL
        EXEC sp_executesql @sqlExclude;
    ALTER TABLE dbo.WooCategoryFilterTbl DROP COLUMN ExcludeFromSync;
END


IF OBJECT_ID(N'dbo.WooCategoryFilterTbl', N'U') IS NOT NULL
   AND COL_LENGTH(N'dbo.WooCategoryFilterTbl', N'RouteToZzName') IS NOT NULL
BEGIN
    DECLARE @sqlZz nvarchar(4000);
    SELECT @sqlZz = N'ALTER TABLE dbo.WooCategoryFilterTbl DROP CONSTRAINT ' + QUOTENAME(dc.name)
    FROM sys.default_constraints dc
    INNER JOIN sys.columns c ON c.default_object_id = dc.object_id
    WHERE dc.parent_object_id = OBJECT_ID(N'dbo.WooCategoryFilterTbl')
      AND c.name = N'RouteToZzName';
    IF @sqlZz IS NOT NULL
        EXEC sp_executesql @sqlZz;
    ALTER TABLE dbo.WooCategoryFilterTbl DROP COLUMN RouteToZzName;
END

IF OBJECT_ID(N'dbo.WooAttributeParentTbl', N'U') IS NOT NULL AND COL_LENGTH(N'dbo.WooAttributeParentTbl', N'QtyRank') IS NOT NULL AND COL_LENGTH(N'dbo.WooAttributeParentTbl', N'ImportChannel') IS NOT NULL BEGIN UPDATE dbo.WooAttributeParentTbl SET NoteRank = 1 WHERE QtyRank = 0 AND PackRank = 0 AND NoteRank = 0 AND ImportChannel IN (N'Notes', N'OrderNotes', N'ToNotes');
UPDATE dbo.WooAttributeParentTbl SET PackRank = 1 WHERE QtyRank = 0 AND PackRank = 0 AND NoteRank = 0 AND ImportChannel IN (N'PackWins', N'PrepPack');
UPDATE dbo.WooAttributeParentTbl SET QtyRank = 1, PackRank = 2 WHERE QtyRank = 0 AND PackRank = 0 AND NoteRank = 0 AND ImportChannel IN (N'QtyPackFallback', N'QtyFallback', N'PackFallback');
UPDATE dbo.WooAttributeParentTbl SET QtyRank = 1, PackRank = 1 WHERE QtyRank = 0 AND PackRank = 0 AND NoteRank = 0 AND ImportChannel IN (N'Line'); END
